  "code": {
   "intro": "New tools: tone(pin, frequency) plays a sound and noTone(pin) stops it. waitAndCheck() works like delay(), but it keeps watching the button while it waits. Fill in the blanks.",
   "lines": [
    "// Names: ______________ & ______________",
    "// Session 8 - Smart Crosswalk",
    "// What this program does: ______________________________",
    "const int RED = 25;       const int WALK = 32;",
    "const int YELLOW = 26;    const int DONT_WALK = 33;",
    "const int GREEN = 27;     const int BUTTON = 16;",
    "const int BUZZER = 23;",
    "bool walkRequested = false;       // has someone pressed WALK?",
    "void waitAndCheck(unsigned long ms) {   // like delay(), but watches the button",
    "  unsigned long start = millis();",
    "  while (millis() - start < ms) {",
    "    if (digitalRead(BUTTON) == HIGH) {",
    "      walkRequested = true;",
    "    }",
    "    delay(10);",
    "  }",
    "}",
    "void setup() {",
    "  pinMode(RED, OUTPUT);   pinMode(YELLOW, OUTPUT);   pinMode(GREEN, OUTPUT);",
    "  pinMode(WALK, OUTPUT);  pinMode(DONT_WALK, OUTPUT); pinMode(BUTTON, INPUT);",
    "  digitalWrite(DONT_WALK, HIGH);  // people wait at the start",
    "}",
    "void loop() {",
    "  digitalWrite(GREEN, HIGH);      // cars go",
    "  waitAndCheck(5000);",
    "  digitalWrite(GREEN, LOW);",
    "  digitalWrite(______, HIGH);     // cars slow down",
    "  waitAndCheck(______);",
    "  digitalWrite(______, LOW);",
    "  digitalWrite(RED, HIGH);        // cars stop",
    "  if (walkRequested) {            // someone pressed WALK",
    "    digitalWrite(DONT_WALK, ____);",
    "    digitalWrite(WALK, ____);",
    "    for (int i = 0; i < 10; i++) {  // 10 chirps, about 5 seconds",
    "      tone(BUZZER, 2000);",
    "      delay(50);",
    "      noTone(______);",
    "      delay(450);",
    "    }",
    "    digitalWrite(WALK, ____);",
    "    digitalWrite(DONT_WALK, ____);",
    "    walkRequested = ______;       // request handled",
    "  } else {",
    "    waitAndCheck(3000);           // normal red light",
    "  }",
    "  digitalWrite(RED, LOW);",
    "}"
   ],
   "remember": "Remember: Higher frequency = higher pitch · Test the lights first, then add the button, then the buzzer"
  },
  "stretch": {
   "text": "Make the chirps speed up in the last 2 seconds of WALK, like real crosswalks. Or add a second traffic light for the cross street (the full Challenge 7c).",
   "hint": "Split the chirp loop into two loops: a slow one (delay(450)) and a fast one (delay(150))."
  },
